import { html, styled } from '@tamagui/tailwind'

<html.button
  className="px-4 py-2 rounded-lg
             bg-blue-500 hover:bg-blue-600"
>
  <html.span className="text-white">Ship it</html.span>
</html.button>

// or lift it into a component
const Button = styled(html.button, 'px-4 py-2 rounded-lg', {
  variants: {
    tone: {
      solid: 'bg-blue-500 hover:bg-blue-600',
      ghost: 'hover:bg-blue-50',
    },
  },
})

